import pandas as pd

def order_two_columns(data: pd.DataFrame) -> pd.DataFrame:
    s1 = data['first_col'].sort_values().reset_index(drop=True)
    s2 = data['second_col'].sort_values(ascending=False).reset_index(drop=True)
    return pd.DataFrame({'first_col': s1, 'second_col': s2})
